/**
* The `Matter.Query` module contains methods for performing collision queries.
*
* See the included usage [examples](https://github.com/liabru/matter-js/tree/master/examples).
*
* @class Query
*/

import Vector from '../geometry/Vector.js';
import Collision from './Collision.js';
import Bounds from '../geometry/Bounds.js';
import Bodies from '../factory/Bodies.js';
import Vertices from '../geometry/Vertices.js';

class Query {
    /**
     * Returns a list of collisions between `body` and `bodies`.
     * @method collides
     * @param {body} body
     * @param {body[]} bodies
     * @return {collision[]} Collisions
     */
    static collides(body, bodies) {
        const collisions = [],
            bodiesLength = bodies.length,
            bounds = body.bounds,
            collides = Collision.collides,
            overlaps = Bounds.overlaps;

        for (let i = 0; i < bodiesLength; i++) {
            const bodyA = bodies[i],
                partsALength = bodyA.parts.length,
                partsAStart = partsALength === 1 ? 0 : 1;

            if (overlaps(bodyA.bounds, bounds)) {
                for (let j = partsAStart; j < partsALength; j++) {
                    const part = bodyA.parts[j];

                    if (overlaps(part.bounds, bounds)) {
                        const collision = collides(part, body);

                        if (collision) {
                            collisions.push(collision);
                            break;
                        }
                    }
                }
            }
        }

        return collisions;
    }

    /**
     * Casts a ray segment against a set of bodies and returns all collisions, ray width is optional. Intersection points are not provided.
     * @method ray
     * @param {body[]} bodies
     * @param {vector} startPoint
     * @param {vector} endPoint
     * @param {number} [rayWidth]
     * @return {collision[]} Collisions
     */
    static ray(bodies, startPoint, endPoint, rayWidth) {
        rayWidth = rayWidth || 1e-100;

        const rayAngle = Vector.angle(startPoint, endPoint),
            rayLength = Vector.magnitude(Vector.sub(startPoint, endPoint)),
            rayX = (endPoint.x + startPoint.x) * 0.5,
            rayY = (endPoint.y + startPoint.y) * 0.5,
            ray = Bodies.rectangle(rayX, rayY, rayLength, rayWidth, { angle: rayAngle }),
            collisions = Query.collides(ray, bodies);

        for (let i = 0; i < collisions.length; i += 1) {
            const collision = collisions[i];
            collision.body = collision.bodyB = collision.bodyA;
        }

        return collisions;
    }

    /**
     * Returns all bodies whose bounds are inside (or outside if set) the given set of bounds, from the given set of bodies.
     * @method region
     * @param {body[]} bodies
     * @param {bounds} bounds
     * @param {bool} [outside=false]
     * @return {body[]} The bodies matching the query
     */
    static region(bodies, bounds, outside) {
        const result = [];

        for (let i = 0; i < bodies.length; i++) {
            const body = bodies[i],
                overlaps = Bounds.overlaps(body.bounds, bounds);
            if ((overlaps && !outside) || (!overlaps && outside))
                result.push(body);
        }

        return result;
    }

    /**
     * Returns all bodies whose vertices contain the given point, from the given set of bodies.
     * @method point
     * @param {body[]} bodies
     * @param {vector} point
     * @return {body[]} The bodies matching the query
     */
    static point(bodies, point) {
        const result = [];

        for (let i = 0; i < bodies.length; i++) {
            const body = bodies[i];

            if (Bounds.contains(body.bounds, point)) {
                for (let j = body.parts.length === 1 ? 0 : 1; j < body.parts.length; j++) {
                    const part = body.parts[j];

                    if (Bounds.contains(part.bounds, point)
                        && Vertices.contains(part.vertices, point)) {
                        result.push(body);
                        break;
                    }
                }
            }
        }

        return result;
    }
}

export default Query;
